    // mode watchwall1120)
    'eyes-pikes-rank-1120': { pri: 2, group: G2, title: 'TRIAL, the test AI: the pikes walk to the rank in round one, no Ready, and throw nothing from it (11-20)', pt: 'the leveling, the formation training -- his "4 - good for test AI" (deep16/js/features.js F.aiWall; js/tactics.js weapons; mode watchwall1120) · eyes',
      obj: 'Watch the formation fight — do the pikes walk behind the shields in round one and fight only with the pike?',
      look: 'His watched door, seed 2. Round one: no Pike holds waiting any more; each walks to the square behind a Shield (one set or still to set, across the front it will face) and the log says it takes the rank, pike levelled. From the rank it strikes with the pike past the shields at 10 ft and never throws a handaxe (on the old AI the pikes threw 1 to 4 a fight from there). A pike with an ogre at its elbow fights where it stands; a Shield set with its back to the map\'s edge has no rank behind it. A trial to watch, his word: not ruled for good.',
      url: 'deep16/?npc=ogre,ogre,ogre,ogre&formation=4,4&lvl=3&watch&seed=2&fresh=1120pr' },
    // THE PIKE WALL (11-21, Shape A, on his "Go on 1-5"; deep16/js/features.js F.setPikes, F.keepBack, F.chargeStep, F.wallPush's brace; mode pikewall1121, watchwall1120)
